WITH parsed AS (SELECT id, customer_id, created_at, coupon_codes, items, attributes, ship_to.city AS ship_city, AGGREGATE(items, 0.0D, (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS cart_value FROM carts) SELECT id, customer_id, created_at, coupon_codes, items, attributes, ship_city, cart_value, SUM(cart_value) OVER w_grp AS cumulative_cart_value, AVG(cart_value) OVER (ORDER BY created_at, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS cart_value_avg_2, NTILE(5) OVER w_running AS cart_value_bucket, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY cart_value DESC NULLS LAST) AS cart_value_percent_rank, ROW_NUMBER() OVER w_grp_2 AS seq_no FROM parsed WINDOW w_grp AS (PARTITION BY customer_id ORDER BY cart_value, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (ORDER BY cart_value DESC, id), w_grp_2 AS (PARTITION BY ship_city, customer_id ORDER BY cart_value, id);
